<?php
require __DIR__ . '/includes/auth.php';
$adminTitle='Services';
$errors=[];$edit=null;
if(isset($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM services WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
if(is_post()){
 verify_csrf();$action=$_POST['action']??'save';
 if($action==='delete'){db()->prepare('DELETE FROM services WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Service deleted.');redirect('admin/services.php');}
 $id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$icon=trim($_POST['icon']??'building-2');$description=trim($_POST['description']??'');$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['is_active'])?1:0;
 if($title==='')$errors[]='Service title is required.';if($description==='')$errors[]='Description is required.';
 if(!$errors){if($id){$stmt=db()->prepare('UPDATE services SET title=?,icon=?,description=?,sort_order=?,is_active=? WHERE id=?');$stmt->execute([$title,$icon,$description,$sort,$active,$id]);}else{$stmt=db()->prepare('INSERT INTO services(title,icon,description,sort_order,is_active) VALUES(?,?,?,?,?)');$stmt->execute([$title,$icon,$description,$sort,$active]);}flash('success','Service saved successfully.');redirect('admin/services.php');}
 $edit=['id'=>$id,'title'=>$title,'icon'=>$icon,'description'=>$description,'sort_order'=>$sort,'is_active'=>$active];
}
$services=db()->query('SELECT * FROM services ORDER BY sort_order,id')->fetchAll();
require __DIR__ . '/includes/header.php';
?>
<div class="grid gap-7 xl:grid-cols-[420px_1fr]"><section class="admin-card p-6"><h2 class="font-display text-2xl font-bold uppercase text-brand-950"><?= $edit?'Edit Service':'Add Service' ?></h2><?php if($errors): ?><div class="mt-4 rounded-xl bg-red-50 p-4 text-sm font-bold text-red-700"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" class="mt-6 grid gap-4"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="grid gap-2 text-sm font-bold">Title<input class="form-input" name="title" value="<?= e($edit['title']??'') ?>" required></label><label class="grid gap-2 text-sm font-bold">Lucide Icon Name<input class="form-input" name="icon" value="<?= e($edit['icon']??'building-2') ?>"><span class="text-xs font-normal text-slate-400">Examples: house, building-2, hammer, sofa</span></label><label class="grid gap-2 text-sm font-bold">Description<textarea class="form-input min-h-36" name="description" required><?= e($edit['description']??'') ?></textarea></label><label class="grid gap-2 text-sm font-bold">Sort Order<input type="number" class="form-input" name="sort_order" value="<?= e($edit['sort_order']??0) ?>"></label><label class="flex items-center gap-3 text-sm font-bold"><input type="checkbox" name="is_active" class="h-5 w-5 rounded" <?= ($edit['is_active']??1)?'checked':'' ?>>Active</label><div class="flex gap-3"><button class="rounded-xl bg-brand-700 px-5 py-3 font-extrabold text-white">Save Service</button><?php if($edit): ?><a href="<?= url('admin/services.php') ?>" class="rounded-xl bg-slate-100 px-5 py-3 font-extrabold">Cancel</a><?php endif; ?></div></form></section><section class="admin-card p-6"><div class="flex items-center justify-between"><h2 class="font-display text-2xl font-bold uppercase text-brand-950">All Services</h2><span class="text-sm font-bold text-slate-400"><?= count($services) ?> items</span></div><div class="table-wrap mt-5"><table class="admin-table"><thead><tr><th>Service</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($services as $service): ?><tr><td><div class="flex items-center gap-3"><span class="grid h-10 w-10 place-items-center rounded-xl bg-brand-50 text-brand-700"><i data-lucide="<?= e($service['icon']) ?>" class="h-5 w-5"></i></span><div><div class="font-extrabold text-brand-950"><?= e($service['title']) ?></div><div class="max-w-md truncate text-xs text-slate-500"><?= e(excerpt($service['description'],80)) ?></div></div></div></td><td><?= (int)$service['sort_order'] ?></td><td><span class="status-badge <?= $service['is_active']?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-600' ?>"><?= $service['is_active']?'Active':'Hidden' ?></span></td><td><div class="flex gap-2"><a href="?edit=<?= (int)$service['id'] ?>" class="rounded-lg bg-blue-50 p-2 text-blue-700"><i data-lucide="pencil" class="h-4 w-4"></i></a><form method="post" data-confirm="Delete this service?"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$service['id'] ?>"><button class="rounded-lg bg-red-50 p-2 text-red-700"><i data-lucide="trash-2" class="h-4 w-4"></i></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div>
